#!/usr/bin/env python3
"""
benchmark.py

A stdlib-only benchmark harness for testing multiple LLM models across:
- /v1/chat/completions
- /v1/responses

It measures:
- TTFT (time to first non-empty content delta) via SSE streaming
- total response time

Usage:
    python benchmark.py --config models.json [--output results.json] [--timeout 10] [--workers 4]
"""

from __future__ import annotations

import argparse
import concurrent.futures
import datetime as dt
import json
import os
import socket
import ssl
import sys
import time
import urllib.error
import urllib.request
import uuid
from typing import Any, Dict, Iterable, Iterator, List, Optional, Tuple


PROMPT = "Reply with exactly one sentence about the color blue."

API_PATHS = {
    "chat_completions": "/v1/chat/completions",
    "responses": "/v1/responses",
}


def positive_int(value: str) -> int:
    try:
        parsed = int(value)
    except ValueError as exc:
        raise argparse.ArgumentTypeError(f"invalid int value: {value}") from exc
    if parsed < 1:
        raise argparse.ArgumentTypeError("value must be >= 1")
    return parsed


def positive_float(value: str) -> float:
    try:
        parsed = float(value)
    except ValueError as exc:
        raise argparse.ArgumentTypeError(f"invalid float value: {value}") from exc
    if parsed <= 0:
        raise argparse.ArgumentTypeError("value must be > 0")
    return parsed


def now_iso_utc() -> str:
    return dt.datetime.now(dt.timezone.utc).isoformat().replace("+00:00", "Z")


def ms(seconds: float) -> float:
    return round(seconds * 1000.0, 1)


def safe_model_id(model_cfg: Any, index: int) -> str:
    if isinstance(model_cfg, dict):
        model_id = model_cfg.get("id")
        if model_id is not None and str(model_id).strip():
            return str(model_id)
    return f"<model_{index}>"


def safe_api_type(model_cfg: Any) -> str:
    if isinstance(model_cfg, dict):
        api_type = model_cfg.get("api_type")
        if api_type is not None and str(api_type).strip():
            return str(api_type)
    return "unknown"


def require_nonempty_str(model_cfg: Dict[str, Any], key: str) -> str:
    value = model_cfg.get(key)
    if not isinstance(value, str) or not value.strip():
        raise ValueError(f"missing or invalid required field: {key}")
    return value


def build_url(model_cfg: Dict[str, Any]) -> str:
    base_url = require_nonempty_str(model_cfg, "base_url").rstrip("/")
    api_type = require_nonempty_str(model_cfg, "api_type")

    if api_type not in API_PATHS:
        raise ValueError(
            f"unsupported api_type '{api_type}' (expected one of: {', '.join(sorted(API_PATHS))})"
        )

    return base_url + API_PATHS[api_type]


def build_payload(model_cfg: Dict[str, Any], prompt: str) -> Dict[str, Any]:
    api_type = require_nonempty_str(model_cfg, "api_type")
    model_id = require_nonempty_str(model_cfg, "id")

    payload: Dict[str, Any] = {
        "model": model_id,
        "stream": True,
    }

    if api_type == "chat_completions":
        payload["messages"] = [{"role": "user", "content": prompt}]
    elif api_type == "responses":
        payload["input"] = prompt
    else:
        raise ValueError(f"unsupported api_type '{api_type}'")

    if "temperature" in model_cfg and model_cfg["temperature"] is not None:
        payload["temperature"] = model_cfg["temperature"]

    if "max_tokens" in model_cfg and model_cfg["max_tokens"] is not None:
        payload["max_tokens"] = model_cfg["max_tokens"]

    # Optional escape hatch for vendor-specific request body parameters.
    extra_body = model_cfg.get("request_options")
    if extra_body is not None:
        if not isinstance(extra_body, dict):
            raise ValueError("request_options must be an object if provided")
        payload.update(extra_body)

    return payload


def build_headers(model_cfg: Dict[str, Any]) -> Dict[str, str]:
    api_key_env = require_nonempty_str(model_cfg, "api_key_env")
    api_key = os.getenv(api_key_env)
    if not api_key:
        raise ValueError(f"environment variable '{api_key_env}' is not set")

    headers: Dict[str, str] = {
        "Content-Type": "application/json",
        "Accept": "text/event-stream",
        "Cache-Control": "no-cache",
        "User-Agent": "benchmark-harness/1.0",
    }

    # Optional extra headers from config.
    raw_headers = model_cfg.get("headers")
    if raw_headers is not None:
        if not isinstance(raw_headers, dict):
            raise ValueError("headers must be an object if provided")
        for key, value in raw_headers.items():
            headers[str(key)] = str(value)

    # Optional customization for auth header.
    api_key_header = str(model_cfg.get("api_key_header", "Authorization"))
    api_key_prefix = model_cfg.get("api_key_prefix")
    if api_key_prefix is None:
        api_key_prefix = "Bearer " if api_key_header.lower() == "authorization" else ""

    existing_header_names = {k.lower() for k in headers.keys()}
    if api_key_header.lower() not in existing_header_names:
        headers[api_key_header] = str(api_key_prefix) + api_key

    return headers


def iter_sse_data_events(response: Any) -> Iterator[str]:
    """
    Parse SSE manually from a file-like HTTP response.

    We accumulate all `data:` lines until a blank line, then yield the combined event payload.
    """
    data_lines: List[str] = []

    while True:
        raw_line = response.readline()
        if not raw_line:
            break

        if isinstance(raw_line, bytes):
            line = raw_line.decode("utf-8", errors="replace")
        else:
            line = str(raw_line)

        line = line.rstrip("\r\n")

        if line == "":
            if data_lines:
                yield "\n".join(data_lines)
                data_lines = []
            continue

        if line.startswith(":"):
            # SSE comment / keepalive
            continue

        if line.startswith("data:"):
            data_lines.append(line[5:].lstrip(" "))
            continue

        # Ignore other SSE fields like event:, id:, retry:

    if data_lines:
        yield "\n".join(data_lines)


def extract_error_from_event(event: Any) -> Optional[str]:
    if not isinstance(event, dict):
        return None

    if event.get("type") == "error":
        if isinstance(event.get("error"), dict):
            message = event["error"].get("message")
            if message:
                return str(message)
        if event.get("message"):
            return str(event["message"])
        return json.dumps(event, ensure_ascii=False)

    if "error" in event:
        err = event["error"]
        if isinstance(err, dict):
            message = err.get("message") or err.get("error")
            if message:
                return str(message)
            return json.dumps(err, ensure_ascii=False)
        if err is not None:
            return str(err)

    return None


def extract_text_chat_completions(event: Any) -> Optional[str]:
    if not isinstance(event, dict):
        return None

    choices = event.get("choices")
    if not isinstance(choices, list):
        return None

    for choice in choices:
        if not isinstance(choice, dict):
            continue
        delta = choice.get("delta")
        if not isinstance(delta, dict):
            continue

        content = delta.get("content")

        if isinstance(content, str):
            return content

        # Slightly more permissive handling for content arrays.
        if isinstance(content, list):
            parts: List[str] = []
            for item in content:
                if isinstance(item, dict):
                    text = item.get("text")
                    if isinstance(text, str):
                        parts.append(text)
            if parts:
                return "".join(parts)

    return None


def extract_text_responses(event: Any) -> Optional[str]:
    if not isinstance(event, dict):
        return None

    event_type = event.get("type")

    # Required format from the prompt:
    # data: {"type": "content_block_delta", "delta": {"text": "..."}}
    if event_type == "content_block_delta":
        delta = event.get("delta")
        if isinstance(delta, dict):
            text = delta.get("text")
            if isinstance(text, str):
                return text

    # Helpful compatibility with some Responses-style SSE variants.
    if event_type == "response.output_text.delta":
        delta = event.get("delta")
        if isinstance(delta, str):
            return delta
        if isinstance(delta, dict):
            text = delta.get("text")
            if isinstance(text, str):
                return text

    delta = event.get("delta")
    if isinstance(delta, dict):
        text = delta.get("text")
        if isinstance(text, str):
            return text

    return None


def extract_text_for_api(api_type: str, event: Any) -> Optional[str]:
    if api_type == "chat_completions":
        return extract_text_chat_completions(event)
    if api_type == "responses":
        return extract_text_responses(event)
    return None


def read_http_error_body(exc: urllib.error.HTTPError) -> str:
    try:
        body = exc.read()
    except Exception:
        return ""
    if not body:
        return ""
    try:
        return body.decode("utf-8", errors="replace").strip()
    except Exception:
        return ""


def make_result(
    model_id: str,
    api_type: str,
    status: str,
    ttft_ms: Optional[float],
    total_ms: Optional[float],
    first_token: Optional[str],
    full_response: Optional[str],
    error: Optional[str],
) -> Dict[str, Any]:
    return {
        "model_id": model_id,
        "api_type": api_type,
        "status": status,
        "ttft_ms": ttft_ms,
        "total_ms": total_ms,
        "first_token": first_token,
        "full_response": full_response,
        "error": error,
    }


def make_error_result(
    model_id: str,
    api_type: str,
    function_start: float,
    request_start: Optional[float],
    end_time: float,
    error_message: str,
    first_token_time: Optional[float] = None,
    first_token: Optional[str] = None,
) -> Dict[str, Any]:
    start_time = request_start if request_start is not None else function_start
    total_ms = ms(end_time - start_time)
    ttft_ms = (
        ms(first_token_time - request_start)
        if first_token_time is not None and request_start is not None
        else None
    )

    return make_result(
        model_id=model_id,
        api_type=api_type,
        status="error",
        ttft_ms=ttft_ms,
        total_ms=total_ms,
        first_token=first_token,
        full_response=None,
        error=error_message,
    )


def benchmark_model(
    model_cfg: Any,
    prompt: str,
    timeout: float,
    index: int,
) -> Dict[str, Any]:
    model_id = safe_model_id(model_cfg, index)
    api_type = safe_api_type(model_cfg)

    function_start = time.perf_counter()
    request_start: Optional[float] = None
    first_token_time: Optional[float] = None
    first_token: Optional[str] = None
    response_parts: List[str] = []

    try:
        if not isinstance(model_cfg, dict):
            raise ValueError("model config entry must be an object")

        url = build_url(model_cfg)
        api_type = safe_api_type(model_cfg)
        payload = build_payload(model_cfg, prompt)
        headers = build_headers(model_cfg)

        body = json.dumps(payload).encode("utf-8")
        request = urllib.request.Request(
            url=url,
            data=body,
            headers=headers,
            method="POST",
        )

        request_start = time.perf_counter()

        with urllib.request.urlopen(request, timeout=timeout) as response:
            for event_data in iter_sse_data_events(response):
                if not event_data:
                    continue

                if event_data.strip() == "[DONE]":
                    break

                try:
                    event = json.loads(event_data)
                except json.JSONDecodeError as exc:
                    raise ValueError(f"JSON parse error in SSE event: {exc.msg}") from exc

                api_error = extract_error_from_event(event)
                if api_error:
                    raise RuntimeError(api_error)

                chunk = extract_text_for_api(api_type, event)
                if chunk is None:
                    continue

                if first_token_time is None and chunk.strip() != "":
                    first_token_time = time.perf_counter()
                    first_token = chunk

                response_parts.append(chunk)

        end_time = time.perf_counter()
        total_ms = ms((end_time - request_start) if request_start is not None else (end_time - function_start))
        ttft_ms = (
            ms(first_token_time - request_start)
            if first_token_time is not None and request_start is not None
            else None
        )
        full_response = "".join(response_parts)

        return make_result(
            model_id=model_id,
            api_type=api_type,
            status="ok",
            ttft_ms=ttft_ms,
            total_ms=total_ms,
            first_token=first_token,
            full_response=full_response,
            error=None,
        )

    except urllib.error.HTTPError as exc:
        end_time = time.perf_counter()
        message = f"HTTP {exc.code}"
        if exc.reason:
            message += f" {exc.reason}"
        body_text = read_http_error_body(exc)
        if body_text:
            message += f": {body_text}"
        return make_error_result(
            model_id=model_id,
            api_type=api_type,
            function_start=function_start,
            request_start=request_start,
            end_time=end_time,
            error_message=message,
            first_token_time=first_token_time,
            first_token=first_token,
        )

    except urllib.error.URLError as exc:
        end_time = time.perf_counter()
        reason = exc.reason
        if isinstance(reason, socket.timeout):
            message = f"Connection timeout after {int(timeout * 1000)}ms"
        else:
            message = f"Connection error: {reason}"
        return make_error_result(
            model_id=model_id,
            api_type=api_type,
            function_start=function_start,
            request_start=request_start,
            end_time=end_time,
            error_message=message,
            first_token_time=first_token_time,
            first_token=first_token,
        )

    except socket.timeout:
        end_time = time.perf_counter()
        return make_error_result(
            model_id=model_id,
            api_type=api_type,
            function_start=function_start,
            request_start=request_start,
            end_time=end_time,
            error_message=f"Connection timeout after {int(timeout * 1000)}ms",
            first_token_time=first_token_time,
            first_token=first_token,
        )

    except ssl.SSLError as exc:
        end_time = time.perf_counter()
        return make_error_result(
            model_id=model_id,
            api_type=api_type,
            function_start=function_start,
            request_start=request_start,
            end_time=end_time,
            error_message=f"SSL error: {exc}",
            first_token_time=first_token_time,
            first_token=first_token,
        )

    except ValueError as exc:
        end_time = time.perf_counter()
        return make_error_result(
            model_id=model_id,
            api_type=api_type,
            function_start=function_start,
            request_start=request_start,
            end_time=end_time,
            error_message=str(exc),
            first_token_time=first_token_time,
            first_token=first_token,
        )

    except Exception as exc:
        end_time = time.perf_counter()
        return make_error_result(
            model_id=model_id,
            api_type=api_type,
            function_start=function_start,
            request_start=request_start,
            end_time=end_time,
            error_message=f"{type(exc).__name__}: {exc}",
            first_token_time=first_token_time,
            first_token=first_token,
        )


def load_config(config_path: str) -> List[Any]:
    with open(config_path, "r", encoding="utf-8") as f:
        data = json.load(f)

    if not isinstance(data, dict):
        raise ValueError("config file must contain a top-level JSON object")

    models = data.get("models")
    if not isinstance(models, list):
        raise ValueError("config file must contain a 'models' array")

    return models


def summarize_results(results: List[Dict[str, Any]]) -> Dict[str, Any]:
    total = len(results)
    ok_results = [r for r in results if r.get("status") == "ok"]
    error_results = [r for r in results if r.get("status") == "error"]

    ttft_results = [r for r in ok_results if r.get("ttft_ms") is not None]

    avg_ttft_ms: Optional[float] = None
    fastest_model: Optional[str] = None
    slowest_model: Optional[str] = None

    if ttft_results:
        avg_ttft_ms = round(
            sum(float(r["ttft_ms"]) for r in ttft_results) / len(ttft_results),
            1,
        )
        fastest_model = min(ttft_results, key=lambda r: float(r["ttft_ms"]))["model_id"]
        slowest_model = max(ttft_results, key=lambda r: float(r["ttft_ms"]))["model_id"]

    return {
        "total": total,
        "ok": len(ok_results),
        "errors": len(error_results),
        "avg_ttft_ms": avg_ttft_ms,
        "fastest_model": fastest_model,
        "slowest_model": slowest_model,
    }


def run_benchmark(models: List[Any], prompt: str, timeout: float, workers: int) -> List[Dict[str, Any]]:
    if not models:
        return []

    results: List[Optional[Dict[str, Any]]] = [None] * len(models)

    with concurrent.futures.ThreadPoolExecutor(max_workers=workers) as executor:
        future_map: Dict[concurrent.futures.Future, Tuple[int, Any]] = {}

        for index, model_cfg in enumerate(models):
            future = executor.submit(benchmark_model, model_cfg, prompt, timeout, index)
            future_map[future] = (index, model_cfg)

        for future in concurrent.futures.as_completed(future_map):
            index, model_cfg = future_map[future]
            try:
                result = future.result()
            except Exception as exc:
                # Extra safety: never let one worker crash the whole harness.
                model_id = safe_model_id(model_cfg, index)
                api_type = safe_api_type(model_cfg)
                result = make_result(
                    model_id=model_id,
                    api_type=api_type,
                    status="error",
                    ttft_ms=None,
                    total_ms=None,
                    first_token=None,
                    full_response=None,
                    error=f"Unhandled worker exception: {type(exc).__name__}: {exc}",
                )
            results[index] = result

    return [r for r in results if r is not None]


def parse_args(argv: Optional[Iterable[str]] = None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Benchmark LLM models across chat_completions and responses APIs using SSE streaming TTFT measurement."
    )
    parser.add_argument(
        "--config",
        required=True,
        help="Path to model config JSON",
    )
    parser.add_argument(
        "--output",
        default="benchmark_results.json",
        help="Output file path (default: benchmark_results.json)",
    )
    parser.add_argument(
        "--timeout",
        type=positive_float,
        default=30.0,
        help="Per-model timeout in seconds (default: 30)",
    )
    parser.add_argument(
        "--workers",
        type=positive_int,
        default=1,
        help="Parallel workers (default: 1)",
    )
    return parser.parse_args(argv)


def write_json_file(path: str, data: Dict[str, Any]) -> None:
    output_dir = os.path.dirname(os.path.abspath(path))
    if output_dir:
        os.makedirs(output_dir, exist_ok=True)

    with open(path, "w", encoding="utf-8") as f:
        json.dump(data, f, indent=2, ensure_ascii=False)
        f.write("\n")


def main(argv: Optional[Iterable[str]] = None) -> int:
    args = parse_args(argv)

    try:
        models = load_config(args.config)
    except FileNotFoundError:
        print(f"Error: config file not found: {args.config}", file=sys.stderr)
        return 1
    except json.JSONDecodeError as exc:
        print(f"Error: invalid JSON in config file: {exc}", file=sys.stderr)
        return 1
    except Exception as exc:
        print(f"Error loading config: {exc}", file=sys.stderr)
        return 1

    run_id = str(uuid.uuid4())
    timestamp = now_iso_utc()

    results = run_benchmark(
        models=models,
        prompt=PROMPT,
        timeout=args.timeout,
        workers=args.workers,
    )

    output = {
        "run_id": run_id,
        "timestamp": timestamp,
        "prompt": PROMPT,
        "results": results,
        "summary": summarize_results(results),
    }

    try:
        write_json_file(args.output, output)
    except Exception as exc:
        print(f"Error writing output file: {exc}", file=sys.stderr)
        return 1

    print(f"Wrote results to {args.output}")
    print(
        f"Summary: total={output['summary']['total']} "
        f"ok={output['summary']['ok']} "
        f"errors={output['summary']['errors']}"
    )

    return 0


if __name__ == "__main__":
    sys.exit(main())
